const raw = $input.first().json;

// Parser le body — supporte tous les formats
let data = raw;
if (raw.body !== undefined) {
  let rawBody = raw.body;
  if (typeof rawBody === 'string') {
    rawBody = rawBody.replace(/^=+/, '').trim();
    try { data = JSON.parse(rawBody); } catch(e) { data = raw; }
  } else if (typeof rawBody === 'object') {
    data = rawBody;
  }
}

// Fallback — chercher task_id dans raw si pas dans data
const task_id     = data.task_id     || raw.task_id     || 'TASK-MONITORING-' + Date.now();
const environment = data.environment || raw.environment || 'staging';
const service_url = data.service_url || raw.service_url || 'https://app-' + environment + '.monprojet.com';

return [{
  json: {
    task_id:     String(task_id),
    environment: String(environment),
    service_url: String(service_url),
    simulate:    String(data.simulate || 'healthy'),
    thresholds: {
      response_time_ms:   Number(data.thresholds?.response_time_ms   || 2000),
      error_rate_percent: Number(data.thresholds?.error_rate_percent || 5),
      uptime_percent:     Number(data.thresholds?.uptime_percent     || 99)
    }
  }
}];

const input = $input.first().json;

return [{
  json: {
    success: false,
    agent: "Agent Monitoring",
    task_id: "unknown",
    status: "ERROR",
    error_code: input.error_code,
    error_message: input.error_message,
    approved_for_pipeline: false,
    timestamp: input.timestamp
  }
}];

const input = $input.first().json;

const url = (input.service_url || '').toLowerCase();
const simulate = (input.simulate || '').toLowerCase();
const thresholds = input.thresholds || {
  response_time_ms: 2000,
  error_rate_percent: 5,
  uptime_percent: 99
};

const is_down = simulate === 'critical'
  || url.includes('down') || url.includes('fail') || url.includes('error');

const is_slow = simulate === 'degraded'
  || url.includes('slow') || url.includes('perf') || url.includes('lag');

const response_time_ms = is_down ? 9999 : is_slow ? 3500 : 350;
const metrics = {
  response_time_ms,
  error_rate_percent: is_down ? 100 : 1.2,
  uptime_percent: is_down ? 0 : 99.8
};

const violations = [];
if (metrics.response_time_ms > thresholds.response_time_ms)
  violations.push(`Response time ${metrics.response_time_ms}ms > seuil ${thresholds.response_time_ms}ms`);
if (metrics.error_rate_percent > thresholds.error_rate_percent)
  violations.push(`Error rate ${metrics.error_rate_percent}% > seuil ${thresholds.error_rate_percent}%`);
if (metrics.uptime_percent < thresholds.uptime_percent)
  violations.push(`Uptime ${metrics.uptime_percent}% < seuil ${thresholds.uptime_percent}%`);

let monitoring_status;
if (is_down || violations.length >= 2) monitoring_status = 'CRITICAL';
else if (is_slow || violations.length === 1) monitoring_status = 'DEGRADED';
else monitoring_status = 'HEALTHY';

return [{
  json: {
    task_id: input.task_id,
    environment: input.environment,
    service_url: input.service_url,
    monitoring_status,
    metrics,
    violations,
    recommendations: monitoring_status === 'CRITICAL'
      ? ['Intervention immédiate requise', 'Vérifier les logs', 'Considérer un rollback']
      : monitoring_status === 'DEGRADED'
        ? ['Surveiller évolution', 'Analyser logs de performance']
        : []
  }
}];

const input = $input.first().json;

const statusMap = {
  HEALTHY: 'PASS',
  DEGRADED: 'NEEDSIMPROVEMENT',
  CRITICAL: 'FAIL'
};

const status = statusMap[input.monitoring_status] || 'FAIL';
const scoreMap = { PASS: 100, NEEDSIMPROVEMENT: 65, FAIL: 0 };

return [{
  json: {
    agent: "Agent Monitoring",
    task_id: input.task_id,
    status,
    global_score: scoreMap[status],
    approved_for_pipeline: status === 'PASS',
    language: "javascript",
    critical_issues: status === 'FAIL'
      ? input.violations.map(v => ({ severity: "high", description: v }))
      : [],
    warnings: status === 'NEEDSIMPROVEMENT'
      ? input.violations.map(v => ({ severity: "medium", description: v }))
      : [],
    recommendations: input.recommendations || [],
    summary: `Service ${input.monitoring_status} — ${input.violations.length} violation(s)`,
    dimensions: {
      security: { score: 100 },
      quality: { score: scoreMap[status] }
    },
    monitoring_status: input.monitoring_status,
    metrics: input.metrics,
    timestamp: new Date().toISOString()
  }
}];

const input = $input.first().json;
return [{
  json: {
    success: true,
    agent: "Agent Monitoring",
    task_id: input.task_id,
    status: "PASS",
    global_score: input.global_score,
    approved_for_pipeline: true,
    monitoring_status: input.monitoring_status,
    metrics: input.metrics,
    critical_issues: [],
    warnings: [],
    recommendations: input.recommendations || [],
    summary: input.summary,
    dimensions: input.dimensions,
    timestamp: input.timestamp
  }
}];

const input = $input.first().json;
return [{
  json: {
    success: null,
    agent: "Agent Monitoring",
    task_id: input.task_id,
    status: "NEEDSIMPROVEMENT",
    global_score: input.global_score,
    approved_for_pipeline: false,
    monitoring_status: input.monitoring_status,
    metrics: input.metrics,
    critical_issues: [],
    warnings: input.warnings || [],
    recommendations: input.recommendations || [],
    summary: input.summary,
    dimensions: input.dimensions,
    timestamp: input.timestamp
  }
}];

const input = $input.first().json;
return [{
  json: {
    success: false,
    agent: "Agent Monitoring",
    task_id: input.task_id,
    status: "FAIL",
    global_score: 0,
    approved_for_pipeline: false,
    monitoring_status: input.monitoring_status,
    metrics: input.metrics,
    critical_issues: input.critical_issues || [],
    warnings: [],
    recommendations: input.recommendations || [],
    summary: input.summary,
    dimensions: input.dimensions,
    timestamp: input.timestamp
  }
}];
